use serde_json::Value;
use std::collections::BTreeSet;

#[test]
fn main_window_grants_only_default_and_required_window_mutations() {
    let capability: Value =
        serde_json::from_str(include_str!("../capabilities/main.json")).unwrap();
    let permissions = capability["permissions"]
        .as_array()
        .unwrap()
        .iter()
        .map(|permission| permission.as_str().unwrap())
        .collect::<BTreeSet<_>>();

    // Lifecycle, close-to-tray, updater, menu/tray intent, and floating-picker
    // commands are explicit allow-* app permissions generated by the app
    // manifest (no default rule exists, so every granted command is listed
    // here and nothing else may call them).
    assert_eq!(
        permissions,
        BTreeSet::from([
            "core:default",
            "notification:default",
            "core:window:allow-close",
            "core:window:allow-minimize",
            "core:window:allow-toggle-maximize",
            "allow-app-get-launch-context",
            "allow-app-stage-shutdown-checkpoint",
            "allow-app-request-shutdown",
            "allow-app-acknowledge-shutdown",
            "allow-app-cancel-shutdown",
            "allow-app-confirm-and-execute-shutdown",
            "allow-window-hide-to-tray-if-enabled",
            "allow-window-set-minimize-to-tray-on-close",
            "allow-update-get-status",
            "allow-update-check",
            "allow-update-download",
            "allow-update-install",
            "allow-ui-open-settings",
            "allow-ui-consume-pending-open-settings",
            "allow-ui-open-setup-guide",
            "allow-ui-open-feature-tour",
            "allow-ui-open-crash-report",
            "allow-ui-consume-pending-skill-share",
            "allow-update-get-version",
            "allow-update-dismiss-nudge",
            "allow-update-dismiss-available-update",
            "allow-update-list-builds",
            "allow-update-get-linux-package-install-instructions",
            "allow-update-show-linux-package",
            "allow-fs-authorize-external-path",
            "allow-fs-list-files",
            "allow-fs-list-markdown-documents",
            "allow-fs-import-external-paths",
            "allow-fs-stage-external-paths-for-runtime-upload",
            "allow-fs-resolve-dropped-paths-for-agent",
            "allow-fs-download-remote-file",
            "allow-fs-download-remote-folder",
            "allow-fs-save-downloaded-file",
            "allow-fs-start-download",
            "allow-fs-append-download-chunk",
            "allow-fs-finish-download",
            "allow-fs-cancel-download",
            "allow-fs-read-local-log-tail",
            "allow-fs-start-local-log-tail",
            "allow-fs-stop-local-log-tail",
            "allow-shell-open-url",
            "allow-shell-path-exists",
            "allow-shell-open-path",
            "allow-shell-open-in-file-manager",
            "allow-shell-open-file-path",
            "allow-shell-open-file-uri",
            "allow-shell-open-in-external-editor",
            "allow-shell-pick-directory",
            "allow-shell-pick-attachment",
            "allow-shell-pick-image",
            "allow-shell-pick-repo-icon-image",
            "allow-shell-pick-audio",
            "allow-shell-copy-file",
            "allow-ui-pick-floating-markdown-document",
            "allow-ui-pick-floating-workspace-directory",
            "allow-ui-clipboard-read-text",
            "allow-ui-clipboard-write-text",
            "allow-ui-clipboard-write-terminal-text",
            "allow-ui-export-html-to-pdf",
            "allow-ui-notification-dispatch",
            "allow-ui-notification-dismiss",
            "allow-ui-notification-get-permission-status",
            "allow-ui-notification-open-system-settings",
            "allow-developer-permissions-get-status",
            "allow-developer-permissions-request",
            "allow-developer-permissions-open-settings",
            "allow-developer-permissions-test-local-network-connection",
            "allow-ui-speech-get-catalog",
            "allow-ui-speech-get-model-states",
            "allow-ui-speech-download-model",
            "allow-ui-speech-cancel-download",
            "allow-ui-speech-start-dictation",
            "allow-ui-speech-feed-audio",
            "allow-ui-speech-stop-dictation",
            "allow-terminal-preview-connect",
            "allow-terminal-preview-ack",
            "allow-terminal-preview-input",
            "allow-terminal-preview-fit",
            "allow-terminal-preview-unsubscribe",
            "allow-ui-popup-app-menu",
            "allow-settings-crossgrade-status",
            "allow-settings-crossgrade-migrate",
        ])
    );
}
